const pool = global.get('pool');
if (!pool) return node.error("Database pool not found");

const alarm = msg.payload || {};
const severity = alarm.severity || 'CRITICAL';
const message = alarm.message || 'Unknown Alarm';
const nodeId = alarm.node_id || 'Unknown Node';

const outTelegram = [];
const outGoogleChat = [];
const outEmail = [];

(async () => {
    // ดึงค่าการตั้งค่า Notification ของทุก User ในระบบ
    const [prefsRows] = await pool.query("SELECT prefs FROM user_prefs");

    for (const row of prefsRows) {
        if (!row.prefs) continue;
        const prefs = typeof row.prefs === 'string' ? JSON.parse(row.prefs) : row.prefs;
        const channels = prefs.notificationChannels || [];

        for (const ch of channels) {
            if (!ch.enabled || !ch.target) continue;

            const text = `🚨 [${severity}] Alarm from ${nodeId}:\n${message}`;

            if (ch.id === 'telegram') {
                // สำหรับ Telegram (ต้องมี Bot Token)
                outTelegram.push({ 
                    payload: { 
                        chat_id: ch.target, 
                        text: text 
                    } 
                });
            } else if (ch.id === 'googlechat') {
                // สำหรับ Google Chat Webhook
                outGoogleChat.push({ 
                    url: ch.target, 
                    method: 'POST', 
                    payload: { text: text } 
                });
            } else if (ch.id === 'email') {
                // สำหรับ Email
                outEmail.push({ 
                    payload: text, 
                    topic: `⚠️ [${severity}] CCP Alarm: ${nodeId}`, 
                    to: ch.target 
                });
            }
        }
    }

    // ส่งต่อออกไป 3 Outputs (Telegram, GoogleChat, Email)
    node.send([ outTelegram, outGoogleChat, outEmail ]);
})().catch(e => {
    node.error("Notification Error: " + e.message);
});
return null;
